"""Skip complete assembly only when an existing provider failure proves rejection.

This is a sufficient rejection test, not a new acceptance rule. Empty, absent
or otherwise unrecognized records still reach the original complete validator.
The existing checked partial assembly and all diagnostic outputs are retained.
"""
import bpy
from . import curved_junction_nodes as boundary
from . import curved_patch_provider_nodes as patches,curved_strip_provider_nodes as strips

c=boundary.c
ASSEMBLY_FAMILIES=tuple('Prochitecture Streets / Original local failure assembly candidate v'+str(v) for v in (5,6))


def build():
    name='Prochitecture Streets / Cached provider failure preflight v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Patch Results','Strip Results'):g.socket(key,'NodeSocketGeometry')
    g.socket('May Be Complete','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');failed=0.
    for key,role_name,role in (('Patch Results',patches.PART,3),('Strip Results',strips.PART,2)):
        selected=c._select(g,inp.outputs[key],g.math('COMPARE',c.named(g,role_name,'INT'),role))
        components=g.node('GeometryNodeSeparateComponents','Read both legacy and typed status rows')
        g.bind(selected,components.inputs['Geometry'])
        vertices=g.node('GeometryNodePointsToVertices')
        g.bind(components.outputs['Point Cloud'],vertices.inputs['Points'])
        rows=boundary._join(g,components.outputs['Mesh'],vertices.outputs['Mesh'])
        relevant=1.
        if key=='Strip Results':
            kind=c.named(g,strips.KIND,'INT')
            relevant=g.math('MAXIMUM',g.math('COMPARE',kind,1.),g.math('COMPARE',kind,3.))
        bad=relevant*(1.-c.named(g,'valid','BOOLEAN'))
        failed=failed+c._stat(g,rows,bad,'Sum')
    g.bind(1.-g.math('GREATER_THAN',failed,0.),out.inputs['May Be Complete'])
    return g.g


def candidate(original):
    """Copy the known cached assembly wrapper; preserve all socket identities."""
    if not original.name.startswith(ASSEMBLY_FAMILIES):
        raise ValueError('Require the existing local failure assembly contract')
    complete=[n for n in original.nodes if n.type=='GROUP'
              and n.label=='Keep the accepted complete construction verbatim']
    if len(complete)!=1:raise ValueError('Missing unique complete construction')
    strict=complete[0].node_tree
    # Blender truncates long datablock names. In this known builder family,
    # these geometry sockets are emitted only by the cached-patch/strip branch;
    # the trailing display-name fragments are not a reliable mode indicator.
    sockets={s.name:s.socket_type for s in strict.interface.items_tree
             if s.item_type=='SOCKET' and s.in_out=='INPUT'}
    required=('Patch Results','Strip Results','Corridors','External Approaches',
              'Junctions','Compounds','Logical Clusters','Cluster Sites')
    if (not strict.name.startswith('Prochitecture Streets / Connected curved physical surfaces v11')
            or any(sockets.get(key)!='NodeSocketGeometry' for key in required)):
        raise ValueError(('Require the cached original-span validator contract',strict.name,sockets))
    name=original.name+' / Provider failure preflight v1'
    if name in bpy.data.node_groups:raise ValueError('Use a fresh candidate construction')
    tree=original.copy();tree.name=name
    complete=tree.nodes[complete[0].name]
    inputs=[n for n in tree.nodes if n.type=='GROUP_INPUT']
    if len(inputs)!=1:raise ValueError('Require one canonical group input')
    valid=complete.outputs['Valid'];targets=[link.to_socket for link in valid.links]
    if not targets:raise ValueError('Complete validity has no consumers')
    gate=tree.nodes.new('GeometryNodeGroup');gate.node_tree=build()
    gate.label='A reported provider failure cannot yield complete assembly'
    for key in ('Patch Results','Strip Results'):
        tree.links.new(inputs[0].outputs[key],gate.inputs[key])
    choose=tree.nodes.new('GeometryNodeSwitch');choose.input_type='BOOLEAN'
    choose.label='Skip complete assembly after a proven provider failure'
    tree.links.new(gate.outputs['May Be Complete'],choose.inputs['Switch'])
    tree.links.new(valid,choose.inputs['True']);choose.inputs['False'].default_value=False
    for target in targets:tree.links.new(choose.outputs['Output'],target)
    tree['st_cached_failure_preflight']=1
    return tree


def replace_references(roots):
    pending=list(roots);seen=set()
    while pending:
        tree=pending.pop()
        if tree in seen:continue
        seen.add(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type=='GROUP' and n.node_tree)
    originals=[t for t in seen if t.name.startswith(ASSEMBLY_FAMILIES)]
    if not originals:raise ValueError('No cached local failure assembly found')
    if any(t in roots for t in originals):raise ValueError('Expect the canonical wrapper above local assembly')
    result=[]
    for original in originals:
        # Demand-pruned inspection variants can retain this family name after
        # their unused complete-construction call has already been removed.
        # There is no complete evaluation to avoid in those variants.
        if not any(n.type=='GROUP' and n.label=='Keep the accepted complete construction verbatim'
                   for n in original.nodes):
            result.append(dict(original=original.name,skipped='No complete construction remains'))
            continue
        replacement=candidate(original)
        signature=lambda t:[(s.identifier,s.name,s.in_out,s.socket_type) for s in t.interface.items_tree if s.item_type=='SOCKET']
        if signature(original)!=signature(replacement):raise AssertionError('Assembly interface changed')
        users=original.users;original.user_remap(replacement)
        result.append(dict(original=original.name,candidate=replacement.name,users=users))
    if not any('candidate' in row for row in result):
        raise ValueError('No complete construction remains to optimize')
    return result
